INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l36','a chance in a million','',NULL,'/ə tʃæns ɪn ə ˈmɪljən/','There was a chance in a million she was right.','她说中的可能只有百万分之一。','Winning twice is a chance in a million.','连中两次是极小概率的事。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l36','pour scorn on','',NULL,'/pɔːr skɔːrn ɑːn/','Frank poured scorn on the idea.','弗兰克对这个想法嗤之以鼻。','They poured scorn on his plan.','他们对他的计划冷嘲热讽。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l36','needless to say','',NULL,'/ˈniːdləs tə seɪ/','Needless to say, the man was his brother.','不用说,那人就是他兄弟。','Needless to say, we were thrilled.','不用说,我们兴奋极了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l36','make one''s way','',NULL,'/meɪk wʌnz weɪ/','He made his way home on foot.','他徒步往家走。','She made her way through the crowd.','她从人群中挤了过去。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp1','choice','{"stem":"\"We are less credulous than we ___ to be.\"(过去\"曾经是\"用 ___ to be)","options":["use","would","used","using"],"answer_index":2,"stem_cn":"我们不像从前那么轻信了。","explanation_cn":"过去“曾经是(某种状态)”用 used to be。✓ less credulous than we used to be. ✗ would(不表状态)/ use / using:过去状态用 used to be。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp1','choice','{"stem":"\"A nineteenth-century novelist ___ end his story with wild coincidences.\"(过去反复发生的习惯动作)","options":["would","will","is going to","does"],"answer_index":0,"stem_cn":"十九世纪的小说家总爱用离奇巧合收尾。","explanation_cn":"过去反复发生的习惯动作,可用 would。✓ A novelist would end his story with coincidences. ✗ will(将来)/ is going to / does:过去习惯动作用 would。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp1','choice','{"stem":"\"There ___ to be a river running past the village.\"(过去\"曾经存在\"用 ___ to be)","options":["uses","would","used","is used"],"answer_index":2,"stem_cn":"从前有条河从村边流过。","explanation_cn":"过去“曾经存在”用 there used to be。✓ There used to be a river here. ✗ would(不表状态)/ is used / uses:表“曾经有”用 used to be。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp2','choice','{"stem":"\"Readers happily ___ the fact that the servant was the hero''s mother.\"(\"接受(事实/东西)\"用哪个)","options":["denied","accepted","agreed","refused"],"answer_index":1,"stem_cn":"读者欣然接受了女仆是主人公母亲这一事实。","explanation_cn":"“接受(事实、东西)”用 accept。✓ accepted the fact. ✗ agreed(同意看法)/ refused / denied:接受事实用 accept。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp2','choice','{"stem":"\"I ___ with you that the story is unbelievable.\"(\"同意(某人的看法)\"用哪个)","options":["allow","accept","receive","agree"],"answer_index":3,"stem_cn":"我同意你的看法:这故事难以置信。","explanation_cn":"“同意(某人的看法)”用 agree with sb。✓ I agree with you. ✗ accept(接受)/ receive / allow:同意看法用 agree with。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp2','choice','{"stem":"\"She ___ his gift with a smile.\"(\"收下、接受(礼物)\"用哪个)","options":["agreed","accepted","spoke","thought"],"answer_index":1,"stem_cn":"她微笑着收下了他的礼物。","explanation_cn":"“收下、接受(礼物)”用 accept。✓ accepted his gift. ✗ agreed(同意)/ thought / spoke:接受礼物用 accept。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp3','choice','{"stem":"\"That was the ___ mother.\"(\"主人公的母亲\":单数名词加 ''s)","options":["hero''s","hero","heros","heros''"],"answer_index":0,"stem_cn":"那是主人公的母亲。","explanation_cn":"单数名词的所有格加 ''s。✓ the hero''s mother. ✗ heros''(复数所有格)/ heros / hero:单数所有格用 ''s。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp3','choice','{"stem":"\"The ___ clothes were left in the hall.\"(不规则复数的所有格,直接加 ''s)","options":["childrens","children","children''s","childrens''"],"answer_index":2,"stem_cn":"孩子们的衣服落在了门厅里。","explanation_cn":"children 是不规则复数,所有格直接加 ''s。✓ the children''s clothes. ✗ childrens'' / childrens / children:不规则复数加 ''s。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp3','choice','{"stem":"\"We start in six ___ time.\"(以 s 结尾的复数时间名词加 '')","options":["hours''","hours","hour''s","hourss"],"answer_index":0,"stem_cn":"我们六小时后出发。","explanation_cn":"以 s 结尾的复数时间名词,所有格只加撇号 ''。✓ in six hours'' time. ✗ hour''s(单数)/ hours / hourss:复数 s 后加 ''。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp4','choice','{"stem":"\"After having ___ swept downstream, he was carried far away.\"(After having ___ + 过去分词,完成被动)","options":["being","was","been","be"],"answer_index":2,"stem_cn":"被洪水冲到下游后,他被带到了很远的地方。","explanation_cn":"After having + 过去分词的完成被动:After having been + 过去分词。✓ After having been swept downstream. ✗ be / being / was:此处用 been + 过去分词。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp4','choice','{"stem":"\"After having ___ warned, he still went out in the storm.\"(After having ___ + 过去分词)","options":["being","is","be","been"],"answer_index":3,"stem_cn":"被警告过之后,他还是冒着暴风雨出了门。","explanation_cn":"After having been + 过去分词,表“在被…之后”。✓ After having been warned, he… ✗ be / being / is:用 been + 过去分词。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp4','choice','{"stem":"\"After having ___ repaired, the car ran smoothly.\"(After having ___ + 过去分词)","options":["being","be","been","was"],"answer_index":2,"stem_cn":"修好之后,那辆车跑得很顺。","explanation_cn":"After having been + 过去分词。✓ After having been repaired, the car ran smoothly. ✗ be / being / was:用 been + 过去分词。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp5','choice','{"stem":"\"He was thought ___ died in the flood.\"(be thought + 完成不定式\"据认为已…\")","options":["to have","to have been","having","to"],"answer_index":0,"stem_cn":"人们以为他已在洪水中丧生。","explanation_cn":"be thought + 完成不定式“据认为已经(做过)…”。✓ was thought to have died. ✗ to have been(后不接 died)/ having / to:用 to have + 过去分词。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp5','choice','{"stem":"\"The brother was presumed ___ dead for twenty years.\"(be presumed + 不定式,\"被认为是…\")","options":["be","to be","being","to have"],"answer_index":1,"stem_cn":"二十年来,人们一直以为那兄弟已不在人世。","explanation_cn":"be presumed + 不定式“被认为是…”;presumed to be dead。✓ was presumed to be dead. ✗ being / to have / be:用 to be。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp5','choice','{"stem":"\"The house was believed ___ been washed away.\"(be believed + 完成不定式\"据信已…\")","options":["having","to","to have","to be"],"answer_index":2,"stem_cn":"人们以为那房子已被冲毁。","explanation_cn":"be believed + 完成不定式“据信已经…”。✓ was believed to have been washed away. ✗ to be / having / to:用 to have + 过去分词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp6','choice','{"stem":"\"Someone who believes things too easily is ___.\"(\"轻信的\"用哪个词)","options":["credulous","clever","honest","careful"],"answer_index":0,"stem_cn":"太容易相信别人的人。","explanation_cn":"太容易相信别人的是 credulous(轻信的)。✓ less credulous than before. ✗ careful 小心;✗ honest 诚实;✗ clever 聪明——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp6','choice','{"stem":"\"An ordinary, little-known servant girl is ___.\"(\"不起眼的、无名的\"用哪个词)","options":["famous","rich","obscure","proud"],"answer_index":2,"stem_cn":"不起眼、无名的女仆。","explanation_cn":"不起眼、无名的是 obscure。✓ an obscure servant girl. ✗ famous 出名;✗ rich 富有;✗ proud 骄傲——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',5,'am3_l36_gp6','choice','{"stem":"\"A close likeness between two people is a ___.\"(\"相似之处\"用哪个词)","options":["resemblance","difference","distance","quarrel"],"answer_index":0,"stem_cn":"两人之间明显的相像。","explanation_cn":"两人之间的相像是 resemblance。✓ a close resemblance. ✗ difference 不同;✗ quarrel 争吵;✗ distance 距离——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',6,NULL,'choice','{"stem":"improbable 的意思是:","options":["不大可能的","免费的","普通的","确定的"],"answer_index":0,"explanation_cn":"improbable = 不大可能的。✓ wildly improbable coincidences 离奇得不大可能的巧合。\n顺带记:确定的 = certain;普通的 = ordinary;免费的 = free."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',6,NULL,'choice','{"stem":"presume 的意思是:","options":["否认","假定,认为","证明","忘记"],"answer_index":1,"explanation_cn":"presume = 假定、认为。✓ a brother presumed dead 被认定已死的兄弟。\n顺带记:证明 = prove;否认 = deny;忘记 = forget."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',6,NULL,'choice','{"stem":"downfall 的意思是:","options":["崛起","胜利","婚礼","倒台,垮台"],"answer_index":3,"explanation_cn":"downfall = 倒台、垮台。✓ plotting the hero''s downfall 谋划主人公的垮台。\n顺带记:崛起 = rise;婚礼 = wedding;胜利 = victory."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',6,NULL,'choice','{"stem":"naive 的意思是:","options":["严厉的","天真的","狡猾的","富有的"],"answer_index":1,"explanation_cn":"naive = 天真的、幼稚的。✓ such naive solutions 这种幼稚的收场。\n顺带记:狡猾的 = cunning;严厉的 = strict;富有的 = wealthy."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',6,NULL,'choice','{"stem":"incredible 的意思是:","options":["廉价的","无聊的","平常的","难以置信的"],"answer_index":3,"explanation_cn":"incredible = 难以置信的。✓ coincidences one would find incredible 难以置信的巧合。\n顺带记:平常的 = ordinary;无聊的 = boring;廉价的 = cheap."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',6,NULL,'choice','{"stem":"scorn 的意思是:","options":["赞美","感谢","嘲弄,挖苦","邀请"],"answer_index":2,"explanation_cn":"scorn = 嘲弄、挖苦。✓ poured scorn on the idea 对这想法嗤之以鼻。\n顺带记:赞美 = praise;感谢 = thank;邀请 = invite."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',7,NULL,'cloze','{"stem":"第 1 空","context":"We are less credulous than we ___1___ to be. Long-lost relatives reunited by chance seem like fiction, yet such coincidences do happen. A taxi driver named Frank found a brother who was thought ___2___ have died in a flood. After having ___3___ swept downstream, the brother had survived far away. ___4___ to say, the family was overjoyed to be reunited.","blank_no":1,"options":["used","would","use","using"],"answer_index":0,"explanation_cn":"过去“曾经是”用 used to be。✓ We are less credulous than we used to be."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',7,NULL,'cloze','{"stem":"第 2 空","context":"We are less credulous than we ___1___ to be. Long-lost relatives reunited by chance seem like fiction, yet such coincidences do happen. A taxi driver named Frank found a brother who was thought ___2___ have died in a flood. After having ___3___ swept downstream, the brother had survived far away. ___4___ to say, the family was overjoyed to be reunited.","blank_no":2,"options":["to","having","been","of"],"answer_index":0,"explanation_cn":"be thought + 完成不定式,用 to have + 过去分词。✓ was thought to have died in a flood."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',7,NULL,'cloze','{"stem":"第 3 空","context":"We are less credulous than we ___1___ to be. Long-lost relatives reunited by chance seem like fiction, yet such coincidences do happen. A taxi driver named Frank found a brother who was thought ___2___ have died in a flood. After having ___3___ swept downstream, the brother had survived far away. ___4___ to say, the family was overjoyed to be reunited.","blank_no":3,"options":["been","being","be","was"],"answer_index":0,"explanation_cn":"After having been + 过去分词(完成被动)。✓ After having been swept downstream."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',7,NULL,'cloze','{"stem":"第 4 空","context":"We are less credulous than we ___1___ to be. Long-lost relatives reunited by chance seem like fiction, yet such coincidences do happen. A taxi driver named Frank found a brother who was thought ___2___ have died in a flood. After having ___3___ swept downstream, the brother had survived far away. ___4___ to say, the family was overjoyed to be reunited.","blank_no":4,"options":["Needless","Needing","Need","Needed"],"answer_index":0,"explanation_cn":"“不用说、自然”用 needless to say。✓ Needless to say, the family was overjoyed."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',8,NULL,'choice','{"stem":"How did Mrs. Bassett first suspect the workman was Frank''s brother?","options":["She had met him before","She recognized his voice","She saw his ID card","She noticed his close resemblance to her husband"],"answer_index":3,"explanation_cn":"课文说 Mrs. Bassett commented on the workman''s close resemblance to her husband——她注意到那工人和丈夫长得极像。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',8,NULL,'choice','{"stem":"Why did Frank at first pour scorn on the idea?","options":["He believed his brother had been lost in the flood","He had no brother at all","He disliked the workman","He was in a hurry"],"answer_index":0,"explanation_cn":"课文说 Frank poured scorn on the idea, pointing out that his brother had been lost in the flood——弗兰克以为兄弟早在洪水里没了,所以嗤之以鼻。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',8,NULL,'choice','{"stem":"Why had Henry assumed his family was gone?","options":["They had moved abroad","He had forgotten them","Their house had been washed away in the flood","They never wrote to him"],"answer_index":2,"explanation_cn":"课文说 the family house had been washed away…Assuming that his family had drowned——房子被冲毁,他便以为家人都遇难了。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',9,NULL,'choice','{"stem":"你想说\"我同意你的看法:这故事难以置信\"(agree):","options":["I agree you that the story is unbelievable.","I agree with you that the story is unbelievable.","I accept with you that the story is unbelievable.","I agree with you what the story is unbelievable."],"answer_index":1,"explanation_cn":"“同意某人的看法”用 agree with sb。✓ I agree with you that the story is unbelievable. 场合:表示赞同别人的观点。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',9,NULL,'choice','{"stem":"你想说\"被洪水冲到下游后,他被带到了远方\"(After having been + 过去分词):","options":["After having been sweep downstream, he was carried far away.","After have been swept downstream, he was carried far away.","After having being swept downstream, he was carried far away.","After having been swept downstream, he was carried far away."],"answer_index":3,"explanation_cn":"“在被…之后”用 After having been + 过去分词。✓ After having been swept downstream, he was carried far away. 场合:先被动地经历一件事,再发生下一件。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',9,NULL,'choice','{"stem":"你想说\"人们以为他已在洪水中丧生\"(was thought to have done):","options":["He was thought to have died in the flood.","He was thought having died in the flood.","He was thought to died in the flood.","He was thought to have die in the flood."],"answer_index":0,"explanation_cn":"“据认为已经(做过)…”用 be thought to have + 过去分词。✓ He was thought to have died in the flood. 场合:转述大家的推测。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',10,NULL,'choice','{"stem":"improbable 的意思是:","options":["普通的","不大可能的","免费的","确定的"],"answer_index":1,"explanation_cn":"improbable = 不大可能的。✓ wildly improbable coincidences."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',10,NULL,'choice','{"stem":"scorn 的意思是:","options":["邀请","赞美","嘲弄,挖苦","感谢"],"answer_index":2,"explanation_cn":"scorn = 嘲弄、挖苦。✓ poured scorn on the idea."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',10,NULL,'choice','{"stem":"\"We are less credulous than we ___ to be.\"(过去\"曾经是\"用 ___ to be)","options":["used","using","would","use"],"answer_index":0,"stem_cn":"我们不像从前那么轻信了。","explanation_cn":"过去“曾经是”用 used to be。✓ less credulous than we used to be. ✗ would(不表状态)/ use / using:过去状态用 used to be。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',10,NULL,'choice','{"stem":"\"After having ___ swept downstream, he survived.\"(After having ___ + 过去分词)","options":["being","be","was","been"],"answer_index":3,"stem_cn":"被洪水冲到下游后,他活了下来。","explanation_cn":"After having been + 过去分词(完成被动)。✓ After having been swept downstream, he survived. ✗ be / being / was:用 been + 过去分词。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',10,NULL,'choice','{"stem":"\"a chance in a million\" 的意思是:","options":["确定无疑","微乎其微的机会","一百万美元","每天都有的事"],"answer_index":1,"explanation_cn":"a chance in a million = 微乎其微的机会、百万分之一的可能。✓ a chance in a million that she might be right."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',10,NULL,'choice','{"stem":"\"needless to say\" 的意思是:","options":["无话可说","需要说明","不用说,自然","拒绝回答"],"answer_index":2,"explanation_cn":"needless to say = 不用说、自然。✓ Needless to say, the man was his brother."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',10,NULL,'choice','{"stem":"Why do modern readers dislike nineteenth-century coincidences in novels?","options":["They cannot read old English","They find such naive solutions totally unacceptable","They prefer much longer books","They dislike happy endings"],"answer_index":1,"passage":"We are less credulous than we used to be. In the nineteenth century, a novelist would bring his story to a conclusion by presenting his readers with a series of coincidences, most of them wildly improbable. Readers happily accepted the fact that an obscure servant girl was really the hero''s mother, or that a long-lost brother, presumed dead, was really alive all the time and wickedly plotting the hero''s downfall. Modern readers would find such naive solutions totally unacceptable. Yet, in real life, circumstances do sometimes conspire to bring about coincidences that anyone but a nineteenth-century novelist would find incredible. When I was a boy, my grandfather told me how an American taxi driver, Frank Bassett, found a brother who was thought to have died in a great flood twenty years before. While on a walking tour with his wife, Frank stopped to talk to a workman. After they had gone on, Mrs. Bassett commented on the workman''s close resemblance to her husband and even suggested that he might be his brother. Frank poured scorn on the idea, pointing out that his brother had been lost in the flood long ago. Though Mrs. Bassett knew the story well, she thought that there was a chance in a million that she might be right. A few days later, she sent a boy to the workman to ask him whether his name was Henry Bassett. Needless to say, the man''s name was Henry Bassett, and he really was Frank''s long-lost brother. When the brothers were reunited, Henry explained how it was that he was still alive. After having been swept far downstream by the floodwaters, he had been carried to a distant town and had slowly recovered there, cut off from everyone he knew. He had made his way home on foot, only to find that the family house had been washed away and that no one in the neighborhood knew what had become of the residents. Assuming that his family had drowned in the flood, Henry had settled down in a village fifty miles away, where he had remained ever since.","explanation_cn":"课文说 Modern readers would find such naive solutions totally unacceptable——现代读者觉得这种幼稚收场无法接受。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',10,NULL,'choice','{"stem":"How were the two brothers finally reunited?","options":["Mrs. Bassett sent a boy to ask the workman his name","Frank recognized him at once","They met at a family party","A letter arrived from Henry"],"answer_index":0,"passage":"We are less credulous than we used to be. In the nineteenth century, a novelist would bring his story to a conclusion by presenting his readers with a series of coincidences, most of them wildly improbable. Readers happily accepted the fact that an obscure servant girl was really the hero''s mother, or that a long-lost brother, presumed dead, was really alive all the time and wickedly plotting the hero''s downfall. Modern readers would find such naive solutions totally unacceptable. Yet, in real life, circumstances do sometimes conspire to bring about coincidences that anyone but a nineteenth-century novelist would find incredible. When I was a boy, my grandfather told me how an American taxi driver, Frank Bassett, found a brother who was thought to have died in a great flood twenty years before. While on a walking tour with his wife, Frank stopped to talk to a workman. After they had gone on, Mrs. Bassett commented on the workman''s close resemblance to her husband and even suggested that he might be his brother. Frank poured scorn on the idea, pointing out that his brother had been lost in the flood long ago. Though Mrs. Bassett knew the story well, she thought that there was a chance in a million that she might be right. A few days later, she sent a boy to the workman to ask him whether his name was Henry Bassett. Needless to say, the man''s name was Henry Bassett, and he really was Frank''s long-lost brother. When the brothers were reunited, Henry explained how it was that he was still alive. After having been swept far downstream by the floodwaters, he had been carried to a distant town and had slowly recovered there, cut off from everyone he knew. He had made his way home on foot, only to find that the family house had been washed away and that no one in the neighborhood knew what had become of the residents. Assuming that his family had drowned in the flood, Henry had settled down in a village fifty miles away, where he had remained ever since.","explanation_cn":"课文说 she sent a boy to the workman to ask him whether his name was Henry Bassett——她派男孩去问那工人的名字,才认出兄弟。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',10,NULL,'choice','{"stem":"What was the ''chance in a million''?","options":["That Frank would win money","That the workman really was Frank''s long-lost brother","That the boy would get lost","That the flood would return"],"answer_index":1,"audio":"We are less credulous than we used to be. In the nineteenth century, a novelist would bring his story to a conclusion by presenting his readers with a series of coincidences, most of them wildly improbable. Readers happily accepted the fact that an obscure servant girl was really the hero''s mother, or that a long-lost brother, presumed dead, was really alive all the time and wickedly plotting the hero''s downfall. Modern readers would find such naive solutions totally unacceptable. Yet, in real life, circumstances do sometimes conspire to bring about coincidences that anyone but a nineteenth-century novelist would find incredible. When I was a boy, my grandfather told me how an American taxi driver, Frank Bassett, found a brother who was thought to have died in a great flood twenty years before. While on a walking tour with his wife, Frank stopped to talk to a workman. After they had gone on, Mrs. Bassett commented on the workman''s close resemblance to her husband and even suggested that he might be his brother. Frank poured scorn on the idea, pointing out that his brother had been lost in the flood long ago. Though Mrs. Bassett knew the story well, she thought that there was a chance in a million that she might be right. A few days later, she sent a boy to the workman to ask him whether his name was Henry Bassett. Needless to say, the man''s name was Henry Bassett, and he really was Frank''s long-lost brother. When the brothers were reunited, Henry explained how it was that he was still alive. After having been swept far downstream by the floodwaters, he had been carried to a distant town and had slowly recovered there, cut off from everyone he knew. He had made his way home on foot, only to find that the family house had been washed away and that no one in the neighborhood knew what had become of the residents. Assuming that his family had drowned in the flood, Henry had settled down in a village fifty miles away, where he had remained ever since.","explanation_cn":"课文说 there was a chance in a million that she might be right——那工人真是失散兄弟,正是百万分之一的巧合。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l36',10,NULL,'choice','{"stem":"Where did Henry settle after the flood?","options":["In the same town as before","In another country","On the coast","In a village fifty miles away"],"answer_index":3,"audio":"We are less credulous than we used to be. In the nineteenth century, a novelist would bring his story to a conclusion by presenting his readers with a series of coincidences, most of them wildly improbable. Readers happily accepted the fact that an obscure servant girl was really the hero''s mother, or that a long-lost brother, presumed dead, was really alive all the time and wickedly plotting the hero''s downfall. Modern readers would find such naive solutions totally unacceptable. Yet, in real life, circumstances do sometimes conspire to bring about coincidences that anyone but a nineteenth-century novelist would find incredible. When I was a boy, my grandfather told me how an American taxi driver, Frank Bassett, found a brother who was thought to have died in a great flood twenty years before. While on a walking tour with his wife, Frank stopped to talk to a workman. After they had gone on, Mrs. Bassett commented on the workman''s close resemblance to her husband and even suggested that he might be his brother. Frank poured scorn on the idea, pointing out that his brother had been lost in the flood long ago. Though Mrs. Bassett knew the story well, she thought that there was a chance in a million that she might be right. A few days later, she sent a boy to the workman to ask him whether his name was Henry Bassett. Needless to say, the man''s name was Henry Bassett, and he really was Frank''s long-lost brother. When the brothers were reunited, Henry explained how it was that he was still alive. After having been swept far downstream by the floodwaters, he had been carried to a distant town and had slowly recovered there, cut off from everyone he knew. He had made his way home on foot, only to find that the family house had been washed away and that no one in the neighborhood knew what had become of the residents. Assuming that his family had drowned in the flood, Henry had settled down in a village fifty miles away, where he had remained ever since.","explanation_cn":"课文说 Henry had settled down in a village fifty miles away, where he had remained ever since——亨利在五十英里外的村子定居至今。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l37',3,8,37,'The Westhaven Express','开往威斯特海温的快车','too … to / … enough to do、can''t help·can''t stand·don''t mind + 动名词、否定词句首倒装(Nor/Never/Hardly + 倒装)、passed 与 past 的区别、refuse 与 deny 的区别、borrow 与 lend 的区别(原创承载 NCE3 L37 考点·无需净化:一位乘客上了号称''快车''的火车,却站站慢吞吞,到站找站长投诉,才发现时刻表上一个小星号的脚注写着''此趟已停运''·温情自嘲喜剧;美式化 railroad/schedule/stationmaster)','我们早已习惯认定火车总是准点的。经过多年的耳濡目染,大多数人对铁路时刻表怀有一种不可动摇的信任。轮船可能因风暴而误点,航班可能因恶劣天气而取消,可火车必须准时。只有一场格外大的暴雪,才可能暂时打乱铁路运行。一出岔子,人们总是太容易去责怪铁路公司。事实上,出错的多半是我们自己,而不是他们。查过铁路时刻表后,我满意地发现有一趟开往威斯特海温的快车。它从我家附近的车站直达,全程只要一小时十七分钟。上车时,我忍不住注意到有许多本地人也上了车。当时,我并不觉得这有什么奇怪。我想,除了我以外,大概还有很多人想搭这趟出色的班车。火车在几英里外的小站威德利停下时,我也没觉得意外——再威风的快车也可能被信号灯拦住。可当火车站站都慢吞吞地停时,我开始纳闷了。我这才猛然醒悟:这趟快车根本没有以每小时九十英里的速度飞驰,而是勉强以三十英里的速度哐当哐当地爬。一小时十七分钟过去了,我们连一半路程都没走完。我问一位乘客,这是不是开往威斯特海温的快车,他却压根没听说过这趟车。我下定决心一到站就去投诉。两个小时后,我在威斯特海温站气冲冲地跟站长理论。他矢口否认有这趟车,我便借来他那本时刻表。当我告诉他白纸黑字明明写着时,声音里带着几分得意。他草草扫了一眼,让我再看仔细点。一个小小的星号把我引到页脚的一条注释,上面写着:“此趟班车已停运。”','{"q":"Listen and answer — What mistake did the writer make?","options":["He overlooked a footnote saying the service was suspended","He boarded the wrong train","He forgot his ticket at home","He got off one stop too early"],"answer_index":0}'::jsonb,'{"title":"too…to / enough to / can''t help doing / 否定倒装 / passed vs past / refuse vs deny / borrow vs lend","intro":"①too + 形容词 + to do=“太…以致不能”;… enough to do=“足够…能”。②can''t help / can''t stand / don''t mind 后接动名词:can''t help noticing。③否定词(Never / Hardly / Nor / Little)放句首,句子要倒装(助动词提前)。④passed 是动词 pass 的过去式(时间过去了);past 是介词/形容词/名词(经过、过去的)。⑤refuse to do=拒绝做;deny=否认(某事、否认做过,后接动名词)。⑥borrow=(从别人那)借入;lend=把…借给别人。","table":{"headers":["用法","意思","例子"],"rows":[["too…to / enough to","太…不能 / 足够能","too easy to blame"],["can''t help + 动名词","忍不住做","could not help noticing"],["否定词句首倒装","Nor / Never + 倒装","Nor was I surprised"],["passed/past · refuse/deny · borrow/lend","过去/经过·拒绝/否认·借入/借出","he denied the train''s existence"]]},"specialRules":[{"rule":"passed 是动词(时间过去了:an hour passed);past 是介词/形容词/名词(rushed past;in times past)。别混。","mark":"passed ≠ past"},{"rule":"borrow 是“借进来(向别人借)”:borrow sth from sb;lend 是“借出去(借给别人)”:lend sth to sb。方向相反。","mark":"borrow ≠ lend"},{"rule":"美式:railroad(英式 railway)、schedule(英式 timetable)、stationmaster、conductor(英式 ticket collector)。本课已按美语写。","mark":"railroad / schedule"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l37',1,NULL,'We have learned to expect that trains will be punctual. After years of conditioning, most of us have developed an unshakable faith in railroad schedules. Ships may be delayed by storms; flights may be canceled because of bad weather; but trains must be on time. Only an exceptionally heavy snowfall might temporarily dislocate rail service.','我们早已习惯认定火车总是准点的。经过多年的耳濡目染,大多数人对铁路时刻表怀有一种不可动摇的信任。轮船可能因风暴而误点,航班可能因恶劣天气而取消,可火车必须准时。只有一场格外大的暴雪,才可能暂时打乱铁路运行。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l37',2,NULL,'It is all too easy to blame the railroad company when something goes wrong. The truth is that when mistakes occur, they are more likely to be ours than theirs. After consulting my railroad schedule, I noted with satisfaction that there was an express train to Westhaven. It went direct from my local station, and the journey lasted a mere hour and seventeen minutes.','一出岔子,人们总是太容易去责怪铁路公司。事实上,出错的多半是我们自己,而不是他们。查过铁路时刻表后,我满意地发现有一趟开往威斯特海温的快车。它从我家附近的车站直达,全程只要一小时十七分钟。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l37',3,NULL,'When I boarded the train, I could not help noticing that a great many local people got on as well. At the time, this did not strike me as odd. I reflected that there must be many people besides myself who wished to take advantage of this excellent service. Nor was I surprised when the train stopped at Widley, a tiny station a few miles down the line. Even a mighty express can be held up by signals.','上车时,我忍不住注意到有许多本地人也上了车。当时,我并不觉得这有什么奇怪。我想,除了我以外,大概还有很多人想搭这趟出色的班车。火车在几英里外的小站威德利停下时,我也没觉得意外——再威风的快车也可能被信号灯拦住。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l37',4,NULL,'But when the train dawdled at station after station, I began to wonder. It suddenly dawned on me that this express was not roaring down the line at ninety miles an hour, but barely chugging along at thirty. One hour and seventeen minutes passed, and we had not even covered half the distance. I asked a passenger whether this was the Westhaven Express, but he had never even heard of it. I resolved to lodge a complaint as soon as we arrived.','可当火车站站都慢吞吞地停时,我开始纳闷了。我这才猛然醒悟:这趟快车根本没有以每小时九十英里的速度飞驰,而是勉强以三十英里的速度哐当哐当地爬。一小时十七分钟过去了,我们连一半路程都没走完。我问一位乘客,这是不是开往威斯特海温的快车,他却压根没听说过这趟车。我下定决心一到站就去投诉。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l37',5,NULL,'Two hours later, I was talking angrily to the stationmaster at Westhaven. When he denied the train''s existence, I borrowed his copy of the schedule. There was a note of triumph in my voice when I told him that it was there in black and white. Glancing at it briefly, he told me to look again. A tiny asterisk led me to a footnote at the bottom of the page. It said: ''This service has been suspended.''','两个小时后,我在威斯特海温站气冲冲地跟站长理论。他矢口否认有这趟车,我便借来他那本时刻表。当我告诉他白纸黑字明明写着时,声音里带着几分得意。他草草扫了一眼,让我再看仔细点。一个小小的星号把我引到页脚的一条注释,上面写着:“此趟班车已停运。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
