INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am3_l37','round-trip ticket','return ticket','往返票;美语 round-trip,英式 return') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l37','take advantage of','',NULL,'/teɪk ədˈvæntɪdʒ əv/','I wanted to take advantage of the fast service.','我想搭这趟快车图个方便。','Take advantage of the sunny weather.','趁着好天气好好利用一下。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l37','dawn on','',NULL,'/dɔːn ɑːn/','It suddenly dawned on me that the train was slow.','我忽然醒悟这车很慢。','It dawned on her that she was lost.','她这才意识到自己迷路了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l37','in black and white','',NULL,'/ɪn blæk ənd waɪt/','It was there in black and white.','白纸黑字明明写着。','I want the rules in black and white.','我要把规则白纸黑字写下来。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l37','hold up','',NULL,'/hoʊld ʌp/','The express was held up by signals.','快车被信号灯拦住了。','The traffic held us up for an hour.','堵车耽误了我们一个小时。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp1','choice','{"stem":"\"It is all too easy ___ blame the railroad when a train is late.\"(too + 形容词 + ___ do)","options":["and","for","to","that"],"answer_index":2,"stem_cn":"火车一晚点,人们太容易责怪铁路公司了。","explanation_cn":"too + 形容词 + to do,“太…以致不能”;这里 too easy to blame。✓ too easy to blame the railroad. ✗ for / that / and:too…to 用 to do。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp1','choice','{"stem":"\"The wall is too high ___ climb.\"(too + 形容词 + ___ + 动词,表\"太…而不能\")","options":["that","so","for to","to"],"answer_index":3,"stem_cn":"这墙太高,爬不上去。","explanation_cn":"too + 形容词 + to do。✓ too high to climb. ✗ for to / that / so:too…to 用 to do。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp1','choice','{"stem":"\"The step was low ___ for me to climb.\"(\"足够…以至能\",该填哪个词)","options":["enough","so","very","too"],"answer_index":0,"stem_cn":"台阶够低,我能迈上去。","explanation_cn":"“足够…以至能”用 形容词 + enough + to do。✓ low enough to climb. ✗ too(太…不能)/ so / very:表“足够”用 enough。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp2','choice','{"stem":"\"I could not help ___ that many locals got on the train.\"(can''t help + 动名词\"忍不住做\")","options":["notice","to notice","noticing","noticed"],"answer_index":2,"stem_cn":"我忍不住注意到许多本地人也上了车。","explanation_cn":"can''t help + 动名词,“忍不住做”。✓ could not help noticing. ✗ to notice / notice / noticed:can''t help 后接 -ing。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp2','choice','{"stem":"\"I can''t stand ___ for a delayed train.\"(can''t stand + 动名词\"受不了做\")","options":["to wait","waiting","wait","waited"],"answer_index":1,"stem_cn":"我受不了等一趟晚点的火车。","explanation_cn":"can''t stand + 动名词,“受不了做”。✓ can''t stand waiting. ✗ to wait / wait / waited:can''t stand 后接 -ing。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp2','choice','{"stem":"\"I don''t mind ___ a little longer.\"(don''t mind + 动名词\"不介意做\")","options":["to wait","wait","waiting","waited"],"answer_index":2,"stem_cn":"我不介意再多等一会儿。","explanation_cn":"don''t mind + 动名词,“不介意做”。✓ don''t mind waiting. ✗ to wait / wait / waited:mind 后接 -ing。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp3','choice','{"stem":"\"Nor ___ I surprised when the train stopped again.\"(否定词 nor 句首,要倒装)","options":["I was","were","did","was"],"answer_index":3,"stem_cn":"火车又停时,我也不感到意外。","explanation_cn":"否定词 nor 放句首,句子要倒装(助动词/be 提到主语前)。✓ Nor was I surprised. ✗ I was(未倒装)/ did / were:nor 句首用 was 倒装。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp3','choice','{"stem":"\"Never ___ I seen such a slow express.\"(Never 句首,倒装用助动词提前)","options":["had","was","did have","I had"],"answer_index":0,"stem_cn":"我从没见过这么慢的快车。","explanation_cn":"Never 放句首,倒装把助动词 had 提前。✓ Never had I seen such a slow express. ✗ I had(未倒装)/ did have / was:完成时倒装用 had。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp3','choice','{"stem":"\"Hardly ___ we left the station when it stopped again.\"(Hardly 句首,倒装)","options":["did","we had","were","had"],"answer_index":3,"stem_cn":"我们刚离站,车又停了。","explanation_cn":"Hardly 放句首,倒装把 had 提前(Hardly … when …)。✓ Hardly had we left when it stopped. ✗ we had(未倒装)/ did / were:用 had 倒装。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp4','choice','{"stem":"\"One hour ___ and we had not gone far.\"(\"(时间)过去了\"用动词哪个形式)","options":["passing","passed","passes","past"],"answer_index":1,"stem_cn":"一个小时过去了,我们没走多远。","explanation_cn":"“(时间)过去了”用动词 pass 的过去式 passed。✓ One hour passed. ✗ past(介词/形容词)/ passes / passing:时间过去用动词 passed。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp4','choice','{"stem":"\"The train rushed ___ the tiny station without stopping.\"(\"经过\"用介词/副词哪个)","options":["passed","pass","passing","past"],"answer_index":3,"stem_cn":"火车没停,从那小站呼啸而过。","explanation_cn":"“(从…)经过”用介词/副词 past。✓ rushed past the station. ✗ passed(动词)/ passing / pass:经过用 past。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp4','choice','{"stem":"\"We talked about times ___.\"(\"过去的(时光)\"用哪个)","options":["passed","past","passing","pass"],"answer_index":1,"stem_cn":"我们聊起过去的时光。","explanation_cn":"“过去的(时光)”用 past(形容词/名词)。✓ times past. ✗ passed(动词)/ passing / pass:过去的用 past。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp5','choice','{"stem":"\"The stationmaster ___ that the train existed.\"(\"否认(某事是真的)\"用哪个)","options":["rejected","refused","denied","declined"],"answer_index":2,"stem_cn":"站长否认有这趟车。","explanation_cn":"“否认(某事是真的)”用 deny。✓ denied that the train existed. ✗ refused(拒绝做)/ rejected / declined:否认用 deny。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp5','choice','{"stem":"\"He ___ to help me with my complaint.\"(\"拒绝(做某事)\"用 ___ to do)","options":["agreed","denied","accepted","refused"],"answer_index":3,"stem_cn":"他拒绝帮我处理投诉。","explanation_cn":"“拒绝做某事”用 refuse to do。✓ refused to help me. ✗ denied(否认)/ agreed / accepted:拒绝做用 refuse to do。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp5','choice','{"stem":"\"She ___ taking the money.\"(\"否认做过某事\"用 ___ + 动名词)","options":["wanted","refused","denied","promised"],"answer_index":2,"stem_cn":"她否认拿过那笔钱。","explanation_cn":"“否认做过某事”用 deny + 动名词。✓ denied taking the money. ✗ refused(拒绝)/ wanted / promised:否认做过用 deny + -ing。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp6','choice','{"stem":"\"I ___ his copy of the schedule to check the time.\"(\"(从别人那)借入\"用哪个)","options":["borrowed","gave","lent","kept"],"answer_index":0,"stem_cn":"我借来他那本时刻表查时间。","explanation_cn":"“(从别人那)借入”用 borrow;borrow sth from sb。✓ borrowed his copy. ✗ lent(借出)/ gave / kept:借入用 borrow。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp6','choice','{"stem":"\"Could you ___ me your pen for a moment?\"(\"把…借给别人\"用哪个)","options":["get","borrow","lend","take"],"answer_index":2,"stem_cn":"你能把笔借给我用一下吗?","explanation_cn":"“把…借给别人”用 lend;lend sb sth。✓ lend me your pen. ✗ borrow(借入)/ take / get:借出用 lend。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',5,'am3_l37_gp6','choice','{"stem":"\"He ___ some money from a friend.\"(\"(向别人)借入\"用哪个)","options":["lent","borrowed","paid","owed"],"answer_index":1,"stem_cn":"他向朋友借了些钱。","explanation_cn":"“(向别人)借入”用 borrow;borrow from sb。✓ borrowed money from a friend. ✗ lent(借出)/ paid / owed:借入用 borrow。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',6,NULL,'choice','{"stem":"punctual 的意思是:","options":["迟到的","准时的","礼貌的","懒惰的"],"answer_index":1,"explanation_cn":"punctual = 准时的。✓ trains will be punctual 火车会准点。\n顺带记:迟到的 = late;懒惰的 = lazy;礼貌的 = polite."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',6,NULL,'choice','{"stem":"unshakable 的意思是:","options":["不可动摇的","短暂的","脆弱的","廉价的"],"answer_index":0,"explanation_cn":"unshakable = 不可动摇的。✓ an unshakable faith 不可动摇的信任。\n顺带记:脆弱的 = fragile;短暂的 = brief;廉价的 = cheap."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',6,NULL,'choice','{"stem":"cancel 的意思是:","options":["延长","推迟","取消","举办"],"answer_index":2,"explanation_cn":"cancel = 取消。✓ flights may be canceled 航班可能被取消。\n顺带记:举办 = hold;推迟 = postpone;延长 = extend."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',6,NULL,'choice','{"stem":"dawdle 的意思是:","options":["跳跃","慢吞吞地行动","攀登","飞奔"],"answer_index":1,"explanation_cn":"dawdle = 慢吞吞地行动。✓ the train dawdled at station after station 火车站站慢吞吞。\n顺带记:飞奔 = dash;跳跃 = leap;攀登 = climb."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',6,NULL,'choice','{"stem":"complaint 的意思是:","options":["邀请","赞美","命令","抱怨,投诉"],"answer_index":3,"explanation_cn":"complaint = 抱怨、投诉。✓ lodge a complaint 提出投诉。\n顺带记:赞美 = praise;命令 = order;邀请 = invitation."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',6,NULL,'choice','{"stem":"asterisk 的意思是:","options":["星号(*)","横线","问号","句号"],"answer_index":0,"explanation_cn":"asterisk = 星号(*)。✓ a tiny asterisk 一个小星号。\n顺带记:句号 = period;问号 = question mark;横线 = dash."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',7,NULL,'cloze','{"stem":"第 1 空","context":"Most of us have an unshakable faith that trains are punctual. After consulting my schedule, I boarded what I thought was an express. I could not help ___1___ that many locals got on too. It was all too easy ___2___ trust the timetable. Nor ___3___ I worried at first. But the ''express'' dawdled along, and later the stationmaster ___4___ that such a train existed.","blank_no":1,"options":["noticing","to notice","notice","noticed"],"answer_index":0,"explanation_cn":"can''t help + 动名词,“忍不住做”。✓ I could not help noticing that many locals got on."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',7,NULL,'cloze','{"stem":"第 2 空","context":"Most of us have an unshakable faith that trains are punctual. After consulting my schedule, I boarded what I thought was an express. I could not help ___1___ that many locals got on too. It was all too easy ___2___ trust the timetable. Nor ___3___ I worried at first. But the ''express'' dawdled along, and later the stationmaster ___4___ that such a train existed.","blank_no":2,"options":["to","for","that","and"],"answer_index":0,"explanation_cn":"too + 形容词 + to do。✓ It was all too easy to trust the timetable."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',7,NULL,'cloze','{"stem":"第 3 空","context":"Most of us have an unshakable faith that trains are punctual. After consulting my schedule, I boarded what I thought was an express. I could not help ___1___ that many locals got on too. It was all too easy ___2___ trust the timetable. Nor ___3___ I worried at first. But the ''express'' dawdled along, and later the stationmaster ___4___ that such a train existed.","blank_no":3,"options":["was","I was","did","were"],"answer_index":0,"explanation_cn":"否定词 nor 句首,句子倒装。✓ Nor was I worried at first."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',7,NULL,'cloze','{"stem":"第 4 空","context":"Most of us have an unshakable faith that trains are punctual. After consulting my schedule, I boarded what I thought was an express. I could not help ___1___ that many locals got on too. It was all too easy ___2___ trust the timetable. Nor ___3___ I worried at first. But the ''express'' dawdled along, and later the stationmaster ___4___ that such a train existed.","blank_no":4,"options":["denied","refused","agreed","borrowed"],"answer_index":0,"explanation_cn":"“否认(某事是真的)”用 deny。✓ the stationmaster denied that such a train existed."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',8,NULL,'choice','{"stem":"What faith do most people have, according to the writer?","options":["That flights are always cheap","That ships never sink","That buses are the fastest","That trains are always punctual"],"answer_index":3,"explanation_cn":"课文说 most of us have developed an unshakable faith in railroad schedules——大多数人坚信火车总是准点。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',8,NULL,'choice','{"stem":"When did the writer begin to suspect something was wrong?","options":["When the express dawdled at station after station","When it reached Westhaven early","When the seats were all empty","When it left exactly on time"],"answer_index":0,"explanation_cn":"课文说 when the train dawdled at station after station, I began to wonder——快车站站慢吞吞,他才起疑。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',8,NULL,'choice','{"stem":"What did the tiny asterisk lead to?","options":["A ticket price","A footnote saying the service had been suspended","A written apology","A map of the whole line"],"answer_index":1,"explanation_cn":"课文说 A tiny asterisk led me to a footnote…''This service has been suspended.''——小星号指向的脚注写着此趟已停运。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',9,NULL,'choice','{"stem":"你想说\"火车一晚点,人们太容易责怪铁路公司了\"(too...to):","options":["It is all too easy to blamed the railroad when a train is late.","It is all too easy for blame the railroad when a train is late.","It is all too easy to blame the railroad when a train is late.","It is all too easy blaming the railroad when a train is late."],"answer_index":2,"explanation_cn":"too + 形容词 + to do,“太…以致…”;这里 too easy to blame。✓ It is all too easy to blame the railroad when a train is late. 场合:说某事“太容易(以致)…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',9,NULL,'choice','{"stem":"你想说\"站长否认有这趟车\"(deny):","options":["The stationmaster refused that the train existed.","The stationmaster denied that the train existed.","The stationmaster denied the train to exist.","The stationmaster denied to exist the train."],"answer_index":1,"explanation_cn":"“否认某事是真的”用 deny + that 从句(不用 refuse)。✓ The stationmaster denied that the train existed. 场合:否认某件事存在或属实。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',9,NULL,'choice','{"stem":"你想说\"我借来他那本时刻表\"(borrow):","options":["I borrowed his copy of the schedule.","I borrowed him his copy of the schedule.","I borrowed his copy of the schedule to him.","I lent his copy of the schedule."],"answer_index":0,"explanation_cn":"“(从别人那)借入”用 borrow;borrow sth(from sb)。✓ I borrowed his copy of the schedule. 场合:向别人借东西进来。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',10,NULL,'choice','{"stem":"punctual 的意思是:","options":["准时的","迟到的","懒惰的","礼貌的"],"answer_index":0,"explanation_cn":"punctual = 准时的。✓ trains will be punctual."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',10,NULL,'choice','{"stem":"complaint 的意思是:","options":["命令","赞美","抱怨,投诉","邀请"],"answer_index":2,"explanation_cn":"complaint = 抱怨、投诉。✓ lodge a complaint 提出投诉。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',10,NULL,'choice','{"stem":"\"It is all too easy ___ blame the railroad.\"(too + 形容词 + ___ do)","options":["that","for","and","to"],"answer_index":3,"stem_cn":"太容易责怪铁路公司了。","explanation_cn":"too + 形容词 + to do。✓ It is all too easy to blame the railroad. ✗ for / that / and:too…to 用 to do。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',10,NULL,'choice','{"stem":"\"The stationmaster ___ that the train existed.\"(\"否认(某事)\"用哪个)","options":["agreed","borrowed","denied","refused"],"answer_index":2,"stem_cn":"站长否认有这趟车。","explanation_cn":"“否认(某事)”用 deny。✓ The stationmaster denied that the train existed. ✗ refused(拒绝做)/ agreed / borrowed:否认用 deny。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',10,NULL,'choice','{"stem":"\"in black and white\" 的意思是:","options":["黑白照片","白纸黑字、写得清清楚楚","沉默不语","是非分明"],"answer_index":1,"explanation_cn":"in black and white = 白纸黑字、写得清清楚楚。✓ it was there in black and white 白纸黑字写着。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',10,NULL,'choice','{"stem":"\"it dawned on me\" 的意思是:","options":["我忽然明白过来","我很失望","天亮了","我睡着了"],"answer_index":0,"explanation_cn":"it dawned on me = 我忽然明白、意识到。✓ It suddenly dawned on me that the train was slow."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',10,NULL,'choice','{"stem":"Why did the writer at first think nothing was wrong?","options":["He already knew the train was slow","He had no schedule with him","He had fallen asleep","He assumed many people wanted to use the excellent express"],"answer_index":3,"passage":"We have learned to expect that trains will be punctual. After years of conditioning, most of us have developed an unshakable faith in railroad schedules. Ships may be delayed by storms; flights may be canceled because of bad weather; but trains must be on time. Only an exceptionally heavy snowfall might temporarily dislocate rail service. It is all too easy to blame the railroad company when something goes wrong. The truth is that when mistakes occur, they are more likely to be ours than theirs. After consulting my railroad schedule, I noted with satisfaction that there was an express train to Westhaven. It went direct from my local station, and the journey lasted a mere hour and seventeen minutes. When I boarded the train, I could not help noticing that a great many local people got on as well. At the time, this did not strike me as odd. I reflected that there must be many people besides myself who wished to take advantage of this excellent service. Nor was I surprised when the train stopped at Widley, a tiny station a few miles down the line. Even a mighty express can be held up by signals. But when the train dawdled at station after station, I began to wonder. It suddenly dawned on me that this express was not roaring down the line at ninety miles an hour, but barely chugging along at thirty. One hour and seventeen minutes passed, and we had not even covered half the distance. I asked a passenger whether this was the Westhaven Express, but he had never even heard of it. I resolved to lodge a complaint as soon as we arrived. Two hours later, I was talking angrily to the stationmaster at Westhaven. When he denied the train''s existence, I borrowed his copy of the schedule. There was a note of triumph in my voice when I told him that it was there in black and white. Glancing at it briefly, he told me to look again. A tiny asterisk led me to a footnote at the bottom of the page. It said: ''This service has been suspended.''","explanation_cn":"课文说 there must be many people…who wished to take advantage of this excellent service——他以为大家都是来搭这趟好车的,所以没起疑。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',10,NULL,'choice','{"stem":"What was the writer''s real mistake?","options":["He had missed a tiny asterisk showing the service was suspended","He forgot the departure time","He lost his ticket","He got on the wrong platform"],"answer_index":0,"passage":"We have learned to expect that trains will be punctual. After years of conditioning, most of us have developed an unshakable faith in railroad schedules. Ships may be delayed by storms; flights may be canceled because of bad weather; but trains must be on time. Only an exceptionally heavy snowfall might temporarily dislocate rail service. It is all too easy to blame the railroad company when something goes wrong. The truth is that when mistakes occur, they are more likely to be ours than theirs. After consulting my railroad schedule, I noted with satisfaction that there was an express train to Westhaven. It went direct from my local station, and the journey lasted a mere hour and seventeen minutes. When I boarded the train, I could not help noticing that a great many local people got on as well. At the time, this did not strike me as odd. I reflected that there must be many people besides myself who wished to take advantage of this excellent service. Nor was I surprised when the train stopped at Widley, a tiny station a few miles down the line. Even a mighty express can be held up by signals. But when the train dawdled at station after station, I began to wonder. It suddenly dawned on me that this express was not roaring down the line at ninety miles an hour, but barely chugging along at thirty. One hour and seventeen minutes passed, and we had not even covered half the distance. I asked a passenger whether this was the Westhaven Express, but he had never even heard of it. I resolved to lodge a complaint as soon as we arrived. Two hours later, I was talking angrily to the stationmaster at Westhaven. When he denied the train''s existence, I borrowed his copy of the schedule. There was a note of triumph in my voice when I told him that it was there in black and white. Glancing at it briefly, he told me to look again. A tiny asterisk led me to a footnote at the bottom of the page. It said: ''This service has been suspended.''","explanation_cn":"课文说 A tiny asterisk led me to a footnote…''This service has been suspended.''——他漏看了标着停运的小星号,这才是他的错。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',10,NULL,'choice','{"stem":"How fast was the ''express'' really going?","options":["Over a hundred miles an hour","About thirty miles an hour","Ninety miles an hour","It never moved at all"],"answer_index":1,"audio":"We have learned to expect that trains will be punctual. After years of conditioning, most of us have developed an unshakable faith in railroad schedules. Ships may be delayed by storms; flights may be canceled because of bad weather; but trains must be on time. Only an exceptionally heavy snowfall might temporarily dislocate rail service. It is all too easy to blame the railroad company when something goes wrong. The truth is that when mistakes occur, they are more likely to be ours than theirs. After consulting my railroad schedule, I noted with satisfaction that there was an express train to Westhaven. It went direct from my local station, and the journey lasted a mere hour and seventeen minutes. When I boarded the train, I could not help noticing that a great many local people got on as well. At the time, this did not strike me as odd. I reflected that there must be many people besides myself who wished to take advantage of this excellent service. Nor was I surprised when the train stopped at Widley, a tiny station a few miles down the line. Even a mighty express can be held up by signals. But when the train dawdled at station after station, I began to wonder. It suddenly dawned on me that this express was not roaring down the line at ninety miles an hour, but barely chugging along at thirty. One hour and seventeen minutes passed, and we had not even covered half the distance. I asked a passenger whether this was the Westhaven Express, but he had never even heard of it. I resolved to lodge a complaint as soon as we arrived. Two hours later, I was talking angrily to the stationmaster at Westhaven. When he denied the train''s existence, I borrowed his copy of the schedule. There was a note of triumph in my voice when I told him that it was there in black and white. Glancing at it briefly, he told me to look again. A tiny asterisk led me to a footnote at the bottom of the page. It said: ''This service has been suspended.''","explanation_cn":"课文说 barely chugging along at thirty——这趟“快车”其实只以每小时三十英里慢爬。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l37',10,NULL,'choice','{"stem":"What did the writer decide to do when the train dawdled?","options":["Get off at once","Fall asleep","Lodge a complaint as soon as he arrived","Buy a new ticket"],"answer_index":2,"audio":"We have learned to expect that trains will be punctual. After years of conditioning, most of us have developed an unshakable faith in railroad schedules. Ships may be delayed by storms; flights may be canceled because of bad weather; but trains must be on time. Only an exceptionally heavy snowfall might temporarily dislocate rail service. It is all too easy to blame the railroad company when something goes wrong. The truth is that when mistakes occur, they are more likely to be ours than theirs. After consulting my railroad schedule, I noted with satisfaction that there was an express train to Westhaven. It went direct from my local station, and the journey lasted a mere hour and seventeen minutes. When I boarded the train, I could not help noticing that a great many local people got on as well. At the time, this did not strike me as odd. I reflected that there must be many people besides myself who wished to take advantage of this excellent service. Nor was I surprised when the train stopped at Widley, a tiny station a few miles down the line. Even a mighty express can be held up by signals. But when the train dawdled at station after station, I began to wonder. It suddenly dawned on me that this express was not roaring down the line at ninety miles an hour, but barely chugging along at thirty. One hour and seventeen minutes passed, and we had not even covered half the distance. I asked a passenger whether this was the Westhaven Express, but he had never even heard of it. I resolved to lodge a complaint as soon as we arrived. Two hours later, I was talking angrily to the stationmaster at Westhaven. When he denied the train''s existence, I borrowed his copy of the schedule. There was a note of triumph in my voice when I told him that it was there in black and white. Glancing at it briefly, he told me to look again. A tiny asterisk led me to a footnote at the bottom of the page. It said: ''This service has been suspended.''","explanation_cn":"课文说 I resolved to lodge a complaint as soon as we arrived——他决定一到站就去投诉。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
